//PAT-END
const NT = PT_LEN.length, NI = PI_TYPE.length, NPH = 6;
const POW3 = [1, 3, 9, 27, 81, 243, 729, 2187, 6561, 19683, 59049];

// ---- the board: a padded array, 9 cells to a row, wall (3) around; cell = (row + 1) * 9 + file + 1
const WALL = 3;
const CELL = new Int32Array(64), SQOF = new Int32Array(91).fill(-1);
