  for (let i = 0; i < 3 * 91; i++) { ZLO[i] = rnd(); ZHI[i] = rnd(); }
  for (let c = 0; c < 91; c++) { ZLO[c] = ZHI[c] = 0; ZFLO[c] = ZLO[91 + c] ^ ZLO[182 + c]; ZFHI[c] = ZHI[91 + c] ^ ZHI[182 + c]; }
