  x = c - 1; if (B[x] === opp) { do x -= 1; while (B[x] === opp); if (B[x] === me) return true; }
  x = c + 9; if (B[x] === opp) { do x += 9; while (B[x] === opp); if (B[x] === me) return true; }
  x = c - 9; if (B[x] === opp) { do x -= 9; while (B[x] === opp); if (B[x] === me) return true; }
  x = c + 10; if (B[x] === opp) { do x += 10; while (B[x] === opp); if (B[x] === me) return true; }
  x = c - 10; if (B[x] === opp) { do x -= 10; while (B[x] === opp); if (B[x] === me) return true; }
