  x = c + 9; if (B[x] === opp) { m = 1; x += 9; while (B[x] === opp) { m++; x += 9; } if (B[x] === me) n += m; }
  x = c - 9; if (B[x] === opp) { m = 1; x -= 9; while (B[x] === opp) { m++; x -= 9; } if (B[x] === me) n += m; }
  x = c + 10; if (B[x] === opp) { m = 1; x += 10; while (B[x] === opp) { m++; x += 10; } if (B[x] === me) n += m; }
  x = c - 10; if (B[x] === opp) { m = 1; x -= 10; while (B[x] === opp) { m++; x -= 10; } if (B[x] === me) n += m; }
  x = c + 8; if (B[x] === opp) { m = 1; x += 8; while (B[x] === opp) { m++; x += 8; } if (B[x] === me) n += m; }
  x = c - 8; if (B[x] === opp) { m = 1; x -= 8; while (B[x] === opp) { m++; x -= 8; } if (B[x] === me) n += m; }
