    // the board, the counts, the empties and the hash (the patterns are not kept up to date in the exact search)
    B[c] = me;
    let hl = hlo0 ^ ZLO[me * 91 + c], hh = hhi0 ^ ZHI[me * 91 + c];
    for (let j = fs, je = fs + nf; j < je; j++) { const z = FL[j]; B[z] = me; hl ^= ZFLO[z]; hh ^= ZFHI[z]; }
    HLO = hl; HHI = hh;
    CNT[me] += nf + 1; CNT[opp] -= nf;
    const pc = PRV[c], nc = NXT[c]; NXT[pc] = nc; PRV[nc] = pc;
    par = par0 ^ QBIT[c];
